operations.document:
mutation AddTodo($input: AddTodoInput!) {
  addTodo(input: $input) {
    id
    title
  }
}

query Todo($id: ID!) {
  todo(id: $id) {
    id
    title
    done
    status
    owner {
      name
    }
  }
}

mutation ToggleTodo($id: ID!) {
  toggleTodo(id: $id) {
    id
    done
    status
  }
}

query Search($text: String!) {
  search(text: $text) {
    __typename
    ... on Todo {
      id
      title
    }
    ... on User {
      id
      name
    }
  }
}

query Users {
  users {
    id
    name
    email
  }
}

fragments.document:
fragment TodoItem on Todo {
  id
  title
  done
}
